const status=document.getElementById('status');
document.getElementById('connect').onclick=async()=>{try{const [tab]=await chrome.tabs.query({active:true,currentWindow:true});const url=new URL(tab.url);if(url.protocol!=='https:'||!['flow.google.com','labs.google'].includes(url.hostname)||!url.pathname.includes('project/'))throw Error('Mở một dự án Google Flow trước.');const key=document.getElementById('key').value.trim();if(!/^[a-f0-9]{64}$/.test(key))throw Error('Dán đúng mã ghép nối từ Monday.');await chrome.storage.local.set({key,activeTab:tab.id,channel:crypto.randomUUID()});status.textContent='Đã chọn tab. Quay về Monday và bấm Làm mới; nếu chưa kết nối, tải lại tab Flow.'}catch(e){status.textContent=e.message}};
document.getElementById('disconnect').onclick=async()=>{await chrome.storage.local.remove(['key','activeTab','channel']);status.textContent='Đã dừng. Tác vụ đã gửi trên Google có thể vẫn đang chạy.'};
